// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.cloneimport timber.log.Timberimport com.roshan.persona.voice.capture.AudioCapturePipelineimport com.roshan.persona.voice.speaker.MfccFeatureExtractorimport com.roshan.persona.voice.speaker.SpeakerRecognitionEngineimport com.roshan.persona.voice.speaker.VoicePrintimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContextimport java.util.UUIDimport kotlin.math.PIimport kotlin.math.absimport kotlin.math.lnimport kotlin.math.sinimport kotlin.math.sqrt/** * NOUS — Neural Voice Cloner (§9 Voice Cloning + §18 v2 Fix #3). * * Clones a user's voice from 30+ seconds of audio using the v2 neural TTS * path (Piper/VITS). The cloned voice is used by [EmotionalTtsEngine] in * place of the persona-based voice when the user has enrolled a clone. * * ## v2 Architecture (§18 fix #3) * * ``` * User provides 30+ seconds of audio *     ↓ * 1. Quality check (SNR > 15 dB, no clipping) *     ↓ * 2. Ethical guardrail check (own voice / celebrity / deceased) *     ↓ * 3. Extract speaker embedding (ECAPA-TDNN via Step 5.7) *     ↓ * 4. Extract voice characteristics (pitch, formants, prosody) *     ↓ * 5. Adapt VITS model with speaker embedding (Piper/VITS, 50 MB) *     ↓ * 6. Watermark seed derived from ownerSpeakerId *     ↓ * Store as ClonedVoiceProfile * * At TTS time: * 1. text → VITS model (with embedding injected) → audio * 2. audio → VoiceWatermarker.watermark() → watermarked audio * 3. Output to speaker / Bluetooth * ``` * * ## Why direct neural synthesis (§18) * * v1 used "Android TTS → post-processing voice conversion" which produced * robotic, uncanny-valley speech (MOS 3.8). v2 injects the speaker embedding * directly into the VITS model at synthesis time, so there's no "base TTS" * to convert — the cloned voice is generated natively (MOS 4.2+). * * ## Ethical guardrails (§9) * * Cloning is gated by [EthicalGuardrail]: *  - Own voice → requires voice print match (verify it's really the user). *  - Celebrity → user must acknowledge rights ownership in UI. *  - Deceased loved one → always allowed (grief support). * * All cloned audio is watermarked via [VoiceWatermarker] for deepfake defense. * * ## Testability * * [VitsBackend] is an interface — tests inject a fake. Audio quality metrics * (SNR, clipping) are pure functions. The [EthicalGuardrail] is a pure * stateless class. Only the actual VITS inference requires native code * (Piper/VITS via ONNX Runtime, shipped in :native:piper Year 2). * * @see <a href="docs/strategy/module-5-strategy-v2.md">§9 Voice Cloning, §18 Neural Voice Cloning (Piper/VITS)</a> */class NeuralVoiceCloner(    private val speakerRecognition: SpeakerRecognitionEngine,    private val mfccExtractor: MfccFeatureExtractor,    private val vitsBackend: VitsBackend?,    private val watermarker: VoiceWatermarker,    private val guardrail: EthicalGuardrail = EthicalGuardrail(),    private val inferenceDispatcher: CoroutineDispatcher,) {    /**     * Clone a voice from audio samples.     *     * @param request          the cloning request (ownership type + verification).     * @param ownerSpeakerId   the user's enrolled speaker ID (must match     *                         a [VoicePrint] in the speaker recognition store).     * @param audioSamples     30+ seconds of target voice audio (16 kHz, 16-bit).     * @return the cloned profile, or null if cloning failed (guardrail denied,     *         quality too low, or VITS backend unavailable).     */    suspend fun clone(        request: CloneRequest,        ownerSpeakerId: String,        audioSamples: List<ShortArray>,    ): ClonedVoiceProfile? = withContext(inferenceDispatcher) {        // 1. Ethical guardrail.        when (val decision = guardrail.check(request)) {            is GuardrailDecision.Allowed -> { /* proceed */ }            is GuardrailDecision.Denied -> {                Timber.tag(TAG).w("Clone denied: ${decision.reason}")                return@withContext null            }        }        // 2. Quality check.        val quality = assessQuality(audioSamples)        if (!quality.passes) {            Timber.tag(TAG).w("Clone failed: quality too low (SNR=${quality.snrDb}dB, " +                "duration=${quality.durationSec}s, clipping=${quality.clippingRatio}).")            return@withContext null        }        // 3. Extract speaker embedding via Step 5.7 SpeakerRecognitionEngine.        //    enroll() averages multiple samples → stable embedding.        val voicePrint: VoicePrint? = speakerRecognition.enroll(            speakerId = ownerSpeakerId,            displayName = ownerSpeakerId,  // display name set by caller later            audioSamples = audioSamples,        )        if (voicePrint == null) {            Timber.tag(TAG).w("Clone failed: speaker enrollment failed.")            return@withContext null        }        // 4. Extract voice characteristics (pitch, formants, prosody).        val pitch = estimatePitch(audioSamples.flatMap { it.asList() }.toShortArray())        val formants = estimateFormants(audioSamples.flatMap { it.asList() }.toShortArray())        val prosody = estimateProsody(audioSamples.flatMap { it.asList() }.toShortArray())        // 5. Adapt VITS model with speaker embedding (if backend available).        val profileId = UUID.randomUUID().toString()        val vitsModelPath: String? = if (vitsBackend != null) {            val adaptedPath = "$VITS_MODEL_DIR/clone_${profileId}.onnx"            val success = runCatching {                vitsBackend.adaptModel(                    speakerEmbedding = voicePrint.embedding,                    outputPath = adaptedPath,                )            }.onFailure { Timber.tag(TAG).w("VITS adapt failed — falling back to v1 path.", it) }                .getOrDefault(false)            if (success) adaptedPath else null        } else null        // 6. Watermark seed derived from ownerSpeakerId.        val watermarkSeed = deriveWatermarkSeed(ownerSpeakerId, profileId)        val profile = ClonedVoiceProfile(            profileId = profileId,            ownerSpeakerId = ownerSpeakerId,            embedding = voicePrint.embedding,            pitch = pitch,            formants = formants,            prosody = prosody,            vitsModelPath = vitsModelPath,            watermarkSeed = watermarkSeed,            quality = quality,        )        Timber.tag(TAG).i("Clone created: profileId=$profileId, owner=$ownerSpeakerId, " +            "neural=${profile.supportsNeuralSynthesis}, MOS_target=MOS_4_2_PLUS.")        profile    }    /**     * Synthesize speech in the cloned voice.     *     * Uses the v2 neural path (Piper/VITS) if the profile has an adapted     * model; otherwise returns null (caller falls back to v1 path or     * default persona TTS).     *     * The output is **watermarked** via [VoiceWatermarker] before returning.     *     * @param text     text to synthesize.     * @param profile  the cloned voice profile to use.     * @param userId   the user ID for watermarking (must match profile owner).     * @return watermarked PCM audio (24 kHz, 16-bit), or null if neural     *         synthesis isn't available for this profile.     */    suspend fun synthesize(        text: String,        profile: ClonedVoiceProfile,        userId: String,    ): ShortArray? = withContext(inferenceDispatcher) {        if (text.isBlank()) return@withContext null        if (!profile.supportsNeuralSynthesis) {            Timber.tag(TAG).w("synthesize: profile ${profile.profileId} doesn't support neural synthesis.")            return@withContext null        }        val vits = vitsBackend ?: return@withContext null        // Resolve VITS model path outside the runCatching block —        // returning inside `runCatching {}` is prohibited (it returns from the lambda).        val vitsModelPath = profile.vitsModelPath ?: run {            Timber.tag(TAG).w("synthesize: profile ${profile.profileId} has no VITS model path")            return@withContext null        }        val rawAudio = runCatching {            vits.synthesize(                text = text,                modelPath = vitsModelPath,                speakerEmbedding = profile.embedding,            )        }.onFailure { Timber.tag(TAG).e("VITS synthesis failed", it) }            .getOrNull() ?: return@withContext null        // Watermark the output for deepfake defense.        val watermarked = watermarker.watermark(rawAudio, userId)        watermarked    }    // ──────────────────────────────────────────────────────────────────────    // Audio quality assessment (pure functions).    // ──────────────────────────────────────────────────────────────────────    /**     * Assess the quality of enrollment audio.     *     * Returns a [CloneQualityMetrics] with SNR, duration, and clipping ratio.     * The [CloneQualityMetrics.passes] flag tells the caller whether the     * audio is good enough to clone.     */    internal fun assessQuality(audioSamples: List<ShortArray>): CloneQualityMetrics {        val allSamples = audioSamples.flatMap { it.asList() }.toShortArray()        if (allSamples.isEmpty()) {            return CloneQualityMetrics(snrDb = 0f, durationSec = 0f, clippingRatio = 1f)        }        val durationSec = allSamples.size.toFloat() / AudioCapturePipeline.SAMPLE_RATE        val snrDb = calculateSnr(allSamples)        val clippingRatio = calculateClippingRatio(allSamples)        return CloneQualityMetrics(            snrDb = snrDb,            durationSec = durationSec,            clippingRatio = clippingRatio,        )    }    /**     * Calculate signal-to-noise ratio in dB.     *     * Heuristic: SNR ≈ 10 × log10(signal_power / (signal_power - voice_power))     * where voice_power is the power of chunks with VAD-detected voice, and     * signal_power is the total power. Simplified for v1: use the ratio of     * peak amplitude to RMS amplitude as a proxy.     */    internal fun calculateSnr(samples: ShortArray): Float {        if (samples.isEmpty()) return 0f        var sumSq = 0.0        var peak = 0.0f        for (s in samples) {            val v = s.toFloat() / Short.MAX_VALUE            sumSq += v * v            if (abs(v) > peak) peak = abs(v)        }        val rms = sqrt(sumSq / samples.size)        if (rms <= 0) return 0f        // SNR (crest factor proxy) in dB.        return (20 * ln(peak / rms)).toFloat()    }    /** Fraction of samples that are clipped (at ±MAX_VALUE). */    internal fun calculateClippingRatio(samples: ShortArray): Float {        if (samples.isEmpty()) return 0f        var clipped = 0        for (s in samples) {            if (s == Short.MAX_VALUE || s == Short.MIN_VALUE) clipped++        }        return clipped.toFloat() / samples.size    }    // ──────────────────────────────────────────────────────────────────────    // Voice characteristic estimation (pure functions, simplified for v1).    // ──────────────────────────────────────────────────────────────────────    /**     * Estimate the base pitch (F0) of the cloned voice in Hz.     *     * Simplified: uses autocorrelation on a representative chunk. Real     * implementation would use a proper pitch tracker (e.g., YIN or PYIN).     */    internal fun estimatePitch(samples: ShortArray): Float {        if (samples.size < AudioCapturePipeline.SAMPLE_RATE) return DEFAULT_PITCH_HZ        // Take a 100 ms chunk from the middle (usually has voiced content).        val start = samples.size / 2        val end = minOf(start + AudioCapturePipeline.SAMPLE_RATE / 10, samples.size)        val chunk = samples.copyOfRange(start, end)        // Autocorrelation — find the first peak after the zero-lag peak.        var bestLag = 0        var bestCorr = 0.0        val minLag = AudioCapturePipeline.SAMPLE_RATE / 400  // 400 Hz max        val maxLag = AudioCapturePipeline.SAMPLE_RATE / 80   // 80 Hz min        for (lag in minLag..maxLag) {            var corr = 0.0            for (i in 0 until (chunk.size - lag)) {                corr += chunk[i] * chunk[i + lag]            }            if (corr > bestCorr) {                bestCorr = corr                bestLag = lag            }        }        return if (bestLag > 0) AudioCapturePipeline.SAMPLE_RATE.toFloat() / bestLag        else DEFAULT_PITCH_HZ    }    /** Estimate formant frequencies (F1, F2, F3) via simplified LPC. */    internal fun estimateFormants(samples: ShortArray): Formants {        // v1 heuristic: use fixed defaults based on pitch (male vs female).        val pitch = estimatePitch(samples)        return if (pitch < 165f) {            // Male voice.            Formants(f1 = 500f, f2 = 1500f, f3 = 2500f)        } else {            // Female voice.            Formants(f1 = 600f, f2 = 1700f, f3 = 2800f)        }    }    /** Estimate prosody characteristics (rate, jitter, shimmer). */    internal fun estimateProsody(samples: ShortArray): ProsodyCharacteristics {        // v1 heuristic: use defaults. Real implementation would analyze        // pitch contour and amplitude envelope.        return ProsodyCharacteristics(            rate = DEFAULT_SPEAKING_RATE,            jitter = 0.02f,            shimmer = 0.05f,        )    }    /** Derive a watermark seed from ownerSpeakerId + profileId. */    private fun deriveWatermarkSeed(ownerSpeakerId: String, profileId: String): Long {        var seed = 0L        for (c in ownerSpeakerId) seed = seed * 31 + c.code        for (c in profileId) seed = seed * 31 + c.code        return seed    }    companion object {        /** Minimum total audio duration in seconds (§9: 30 seconds). */        const val MIN_CLONE_AUDIO_SECONDS = 30f        /** Minimum SNR in dB (§9: 15 dB). */        const val MIN_SNR_DB = 15.0f        private const val TAG = "NeuralVoiceCloner"        private const val VITS_MODEL_DIR = "/data/user/0/com.roshan.persona/files/vits"        private const val DEFAULT_PITCH_HZ = 150f        private const val DEFAULT_SPEAKING_RATE = 4.5f  // syllables per second    }}// ──────────────────────────────────────────────────────────────────────────/** * ONNX Runtime backend for Piper/VITS neural TTS. * * Real implementation lives in :native:piper (ships Year 2 per §24). Tests * inject a fake to verify the cloning pipeline without needing ONNX Runtime. * * Two operations: *  - [adaptModel]: takes a speaker embedding and produces a speaker-adapted *    VITS model file on disk. *  - [synthesize]: generates speech audio from text using an adapted model. */interface VitsBackend {    /**     * Adapt the base VITS model with a speaker embedding.     *     * @param speakerEmbedding 192-dim ECAPA-TDNN embedding from Step 5.7.     * @param outputPath       absolute path where the adapted .onnx model     *                         should be written.     * @return true on success, false on failure.     */    suspend fun adaptModel(speakerEmbedding: FloatArray, outputPath: String): Boolean    /**     * Synthesize speech in the cloned voice.     *     * @param text             text to synthesize.     * @param modelPath        path to the adapted VITS model (from [adaptModel]).     * @param speakerEmbedding the speaker embedding (re-injected at synthesis     *                         time for additional conditioning).     * @return PCM 16-bit audio at 24 kHz mono.     */    suspend fun synthesize(text: String, modelPath: String, speakerEmbedding: FloatArray): ShortArray    /** Whether the VITS base model is loaded and ready. */    val isReady: Boolean    /** Release ONNX resources. */    fun release()}

